    velocityMps:{x:0,y:0,z:0},covariance:Array(36).fill(0),stateEpoch:'RELEASE_FIXED_COORDINATE',stateAgeS:0,observationAgeS:0,
    launchStep:simStepCounter,identity:'COORDINATE_SEARCH',cueSource:'ROUTE_PLAN_PRIOR',observationUpdate:false,
    positionVelocityOwner:'OPERATOR_ROUTE_PLAN',covarianceOwner:'NONE_NOT_A_MEASUREMENT',timeOwner:'RELEASE_FIXED_COORDINATE',truthUsed:false,updatesAfterRelease:false});
  const cueHandoff=harpoonCueHandoffB(memory,0);
