    predictionSigmaM:cueHandoff.predictionSigmaM,searchBasketM:cueHandoff.searchBasketM,cueHandoff,
    muzzleM:muzzle,axis,authority:{ok:true,mode:'MANUAL_COORDINATE_SEARCH'},truthUsed:false};
